```dart
@override
Stream<List<NewsModel>> loadCachedThenNetwork(NewsFeedFilter filter) async* {
  // First, emit cached data immediately
  try {
    final cached = await _dbDatasource.getNewsList();
    if (cached.isNotEmpty) {
      yield cached;
    }
  } catch (_) {}

  // Then fetch from network
  try {
    final fresh = await _restDatasource.getNewsList();
    await _dbDatasource.saveNewsList(fresh);
    yield fresh;
  } catch (_) {
    // If network fails, we already emitted cached data
  }
}
```

